module LCS_Avoid_Virus(\n    input clk,\n    input rst_n,\n    input start,\n    input [4:0] s1_char0, s1_char1, s1_char2, s1_char3,\n    input [4:0] s2_char0, s2_char1, s2_char2, s2_char3,\n    input [4:0] virus_char0, virus_char1, virus_char2,\n    output reg [4:0] result_char0, result_char1, result_char2, result_char3,\n    output reg [2:0] result_length,\n    output reg done\n);\n\n    // State declarations\n    localparam [2:0] IDLE     = 3'd0;\n    localparam [2:0] INIT     = 3'd1;\n    localparam [2:0] DP_ITER  = 3'd2;\n    localparam [2:0] FIND_MAX = 3'd3;\n    localparam [2:0] BACKTRACK = 3'd4;\n    localparam [2:0] OUTPUT   = 3'd5;\n    \n    reg [2:0] state, next_state;\n    \n    // Input buffer arrays\n    reg [4:0] s1_reg [0:3];\n    reg [4:0] s2_reg [0:3];\n    reg [4:0] virus_reg [0:2];\n    \n    // DP tables\n    reg [2:0] dp_len [0:4][0:4][0:3];\n    reg [2:0] dp_parent_i [0:4][0:4][0:3];\n    reg [2:0] dp_parent_j [0:4][0:4][0:3];\n    reg [2:0] dp_parent_k [0:4][0:4][0:3];\n    reg [4:0] dp_char [0:4][0:4][0:3];\n    reg dp_valid [0:4][0:4][0:3];\n    \n    // Iteration counters\n    reg [2:0] i_ctr, j_ctr, k_ctr;\n    \n    // Max info\n    reg [2:0] max_len;\n    reg [2:0] max_i, max_j, max_k;\n    \n    // Backtracking\n    reg [4:0] temp_buffer [0:3];\n    reg [2:0] temp_idx;\n    reg [2:0] curr_i, curr_j, curr_k;\n    \n    // KMP helper\n    reg [2:0] k_ctr_temp;\n    reg [2:0] next_k;\n    reg [2:0] i, j, k;\n    \n    // KMP next state\n    function [2:0] kmp_next;\n        input [2:0] cur_k;\n        input [4:0] ch;\n        begin\n            kmp_next = 3'd0;\n            case(cur_k)\n                3'd0: kmp_next = (ch == virus_reg[0]) ? 3'd1 : 3'd0;\n                3'd1: begin\n                    if (ch == virus_reg[1]) kmp_next = 3'd2;\n                    else if (ch == virus_reg[0]) kmp_next = 3'd1;\n                    else kmp_next = 3'd0;\n                end\n                3'd2: begin\n                    if (ch == virus_reg[2]) kmp_next = 3'd3; // full virus match\n                    else if (ch == virus_reg[0]) kmp_next = 3'd1;\n                    else kmp_next = 3'd0;\n                end\n                default: kmp_next = 3'd0;\n            endcase\n        end\n    endfunction\n\n    integer idx_i, idx_j, idx_k;\n    \n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            // Reset all registers\n            state <= IDLE;\n            done <= 1'b0;\n            result_length <= 3'd0;\n            result_char0 <= 5'd0; result_char1 <= 5'd0;\n            result_char2 <= 5'd0; result_char3 <= 5'd0;\n            \n            // Initialize arrays (using loops)\n            for (idx_i = 0; idx_i < 4; idx_i = idx_i + 1) begin\n                s1_reg[idx_i] <= 5'd0;\n                s2_reg[idx_i] <= 5'd0;\n            end\n            for (idx_i = 0; idx_i < 3; idx_i = idx_i + 1) begin\n                virus_reg[idx_i] <= 5'd0;\n            end\n            \n            // Initialize DP tables\n            for (idx_i = 0; idx_i < 5; idx_i = idx_i + 1) begin\n                for (idx_j = 0; idx_j < 5; idx_j = idx_j + 1) begin\n                    for (idx_k = 0; idx_k < 4; idx_k = idx_k + 1) begin\n                        dp_len[idx_i][idx_j][idx_k] <= 3'd0;\n                        dp_parent_i[idx_i][idx_j][idx_k] <= 3'd0;\n                        dp_parent_j[idx_i][idx_j][idx_k] <= 3'd0;\n                        dp_parent_k[idx_i][idx_j][idx_k] <= 3'd0;\n                        dp_char[idx_i][idx_j][idx_k] <= 5'd0;\n                        dp_valid[idx_i][idx_j][idx_k] <= 1'b0;\n                    end\n                end\n            end\n            \n            // Initialize other regs\n            i_ctr <= 3'd0; j_ctr <= 3'd0; k_ctr <= 3'd0;\n            max_len <= 3'd0; max_i <= 3'd0; max_j <= 3'd0; max_k <= 3'd0;\n            temp_idx <= 3'd0;\n            curr_i <= 3'd0; curr_j <= 3'd0; curr_k <= 3'd0;\n            for (idx_i = 0; idx_i < 4; idx_i = idx_i + 1) begin\n                temp_buffer[idx_i] <= 5'd0;\n            end\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        // Load inputs\n                        s1_reg[0] <= s1_char0; s1_reg[1] <= s1_char1;\n                        s1_reg[2] <= s1_char2; s1_reg[3] <= s1_char3;\n                        s2_reg[0] <= s2_char0; s2_reg[1] <= s2_char1;\n                        s2_reg[2] <= s2_char2; s2_reg[3] <= s2_char3;\n                        virus_reg[0] <= virus_char0;\n                        virus_reg[1] <= virus_char1;\n                        virus_reg[2] <= virus_char2;\n                        state <= INIT;\n                    end\n                end\n                \n                INIT: begin\n                    // Initialize DP[0][0][0]\n                    dp_valid[0][0][0] <= 1'b1;\n                    dp_len[0][0][0] <= 3'd0;\n                    \n                    // Set iteration counters\n                    i_ctr <= 3'd0;\n                    j_ctr <= 3'd0;\n                    k_ctr <= 3'd0;\n                    state <= DP_ITER;\n                end\n                \n                DP_ITER: begin\n                    if (i_ctr < 3'd4 || j_ctr < 3'd4 || k_ctr < 3'd3) begin\n                        i = i_ctr; j = j_ctr; k = k_ctr;\n                        \n                        if (dp_valid[i][j][k]) begin\n                            // Skip s1[i]\n                            if (i < 3'd4) begin\n                                if (!dp_valid[i+3'd1][j][k] || \n                                    (dp_len[i][j][k] > dp_len[i+3'd1][j][k])) begin\n                                    dp_valid[i+3'd1][j][k] <= 1'b1;\n                                    dp_len[i+3'd1][j][k] <= dp_len[i][j][k];\n                                    dp_parent_i[i+3'd1][j][k] <= i;\n                                    dp_parent_j[i+3'd1][j][k] <= j;\n                                    dp_parent_k[i+3'd1][j][k] <= k;\n                                    dp_char[i+3'd1][j][k] <= 5'd0;\n                                end\n                            end\n                            \n                            // Skip s2[j]\n                            if (j < 3'd4) begin\n                                if (!dp_valid[i][j+3'd1][k] || \n                                    (dp_len[i][j][k] > dp_len[i][j+3'd1][k])) begin\n                                    dp_valid[i][j+3'd1][k] <= 1'b1;\n                                    dp_len[i][j+1][k] <= dp_len[i][j][k];\n                                    dp_parent_i[i][j+1][k] <= i;\n                                    dp_parent_j[i][j+1][k] <= j;\n                                    dp_parent_k[i][j+1][k] <= k;\n                                    dp_char[i][j+1][k] <= 5'd0;\n                                end\n                            end\n                            \n                            // Match if possible\n                            if ((i < 3'd4) && (j < 3'd4) && (s1_reg[i] == s2_reg[j])) begin\n                                next_k = kmp_next(k, s1_reg[i]);\n                                if (next_k < 3'd3) begin  // Avoid virus string\n                                    if (!dp_valid[i+1][j+1][next_k] || \n                                        (dp_len[i][j][k] + 3'd1 > dp_len[i+1][j+1][next_k])) begin\n                                        dp_valid[i+1][j+1][next_k] <= 1'b1;\n                                        dp_len[i+1][j+1][next_k] <= dp_len[i][j][k] + 3'd1;\n                                        dp_parent_i[i+1][j+1][next_k] <= i;\n                                        dp_parent_j[i+1][j+1][next_k] <= j;\n                                        dp_parent_k[i+1][j+1][next_k] <= k;\n                                        dp_char[i+1][j+1][next_k] <= s1_reg[i];\n                                    end\n                                end\n                            end\n                        end\n                        \n                        // Update counters\n                        if (k_ctr < 3'd3) begin\n                            k_ctr <= k_ctr + 3'd1;\n                        end else begin\n                            k_ctr <= 3'd0;\n                            if (j_ctr < 3'd4) begin\n                                j_ctr <= j_ctr + 3'd1;\n                            end else begin\n                                j_ctr <= 3'd0;\n                                if (i_ctr < 3'd4) begin\n                                    i_ctr <= i_ctr + 3'd1;\n                                end else begin\n                                    // End of DP iteration\n                                    state <= FIND_MAX;\n                                end\n                            end\n                        end\n                    end else begin\n                        state <= FIND_MAX;\n                    end\n                end\n                \n                FIND_MAX: begin\n                    // Find max dp_len[i][j][k]\n                    if (i_ctr < 3'd5) begin\n                        if (j_ctr < 3'd5) begin\n                            if (k_ctr < 3'd3) begin\n                                if (dp_valid[i_ctr][j_ctr][k_ctr] && \n                                    dp_len[i_ctr][j_ctr][k_ctr] > max_len) begin\n                                    max_len <= dp_len[i_ctr][j_ctr][k_ctr];\n                                    max_i <= i_ctr;\n                                    max_j <= j_ctr;\n                                    max_k <= k_ctr;\n                                end\n                                k_ctr <= k_ctr + 3'd1;\n                            end else begin\n                                k_ctr <= 3'd0;\n                                j_ctr <= j_ctr + 3'd1;\n                            end\n                        end else begin\n                            j_ctr <= 3'd0;\n                            i_ctr <= i_ctr + 3'd1;\n                        end\n                    end else begin\n                        state <= BACKTRACK;\n                        curr_i <= max_i; curr_j <= max_j; curr_k <= max_k;\n                        temp_idx <= 3'd0;\n                        // Reset temp_buffer\n                        temp_buffer[0] <= 5'd0; temp_buffer[1] <= 5'd0;\n                        temp_buffer[2] <= 5'd0; temp_buffer[3] <= 5'd0;\n                    end\n                end\n                \n                BACKTRACK: begin\n                    if (temp_idx < 3'd4 && \n                       (curr_i != 3'd0 || curr_j != 3'd0 || curr_k != 3'd0)) begin\n                        if (dp_char[curr_i][curr_j][curr_k] != 5'd0) begin\n                            temp_buffer[temp_idx] <= dp_char[curr_i][curr_j][curr_k];\n                            temp_idx <= temp_idx + 3'd1;\n                        end\n                        curr_i <= dp_parent_i[curr_i][curr_j][curr_k];\n                        curr_j <= dp_parent_j[curr_i][curr_j][curr_k];\n                        curr_k <= dp_parent_k[curr_i][curr_j][curr_k];\n                    end else begin\n                        state <= OUTPUT;\n                    end\n                end\n                \n                OUTPUT: begin\n                    // Reverse order\n                    result_char0 <= temp_buffer[3];\n                    result_char1 <= temp_buffer[2];\n                    result_char2 <= temp_buffer[1];\n                    result_char3 <= temp_buffer[0];\n                    result_length <= temp_idx;\n                    done <= 1'b1;\n                    state <= IDLE;\n                end\n                \n                default: state <= IDLE;\n            endcase\n        end\n    end\nendmodule